package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.shaded.org.mockito.Mockito.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.evosuite.runtime.ViolatedAssumptionAnswer;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LevenshteinDetailedDistance_ESTest_test07 extends LevenshteinDetailedDistance_ESTest_scaffolding {

    @Test(timeout = 4000)
    public void test07() throws Throwable {
        CharBuffer oneCharacterBuffer = CharBuffer.allocate(1);
        Integer threshold = new Integer(1);
        LevenshteinDetailedDistance thresholdedDistance = new LevenshteinDetailedDistance(threshold);

        LevenshteinResults result = thresholdedDistance.apply((CharSequence) oneCharacterBuffer, (CharSequence) "y{Ux1x:{|e");

        assertEquals((-1), (int) result.getDistance());
    }
}
